              isLoading={tutorState.isLoading}
              error={tutorState.error}
              modelMetadata={tutorModel}
              availability={availability}
              onRetryAvailability={refreshAvailability}
              queryText={queryText}
              onQueryChange={setQueryText}
              onRequestHelp={handleRequestHelp}
            />
          )}
        </div>
      </div>
    </div>
  );
};

